// VersionedParserGrammars maps a TypeScript version string to its embedded
// parser grammar. CreateTypescriptParser looks the grammar up here with no
// file I/O. The generic (version == "") path uses ParserGrammarData instead.
var VersionedParserGrammars = map[string]*gt.ParserGrammar{
	`ts1.0`: parserGrammarTs10,
	`ts2.0`: parserGrammarTs20,
	`ts3.0`: parserGrammarTs30,
	`ts4.0`: parserGrammarTs40,
	`ts5.0`: parserGrammarTs50,
	`ts5.8`: parserGrammarTs58,
}
